-- schema_subset_042.sql
-- custom-time-slots, new "Frecuencia" type (workflows/custom-time-slots.md,
-- step slot-type-frequency). A rule is now either 'custom' (the clinic-typed
-- list in `times`, exactly as before) or 'frequency' (a start time, end
-- time and a step in minutes). For a frequency rule, `times` is still
-- filled in (generated by the app on every save), so every existing reader
-- of `times` keeps working unchanged.
--
-- Additive only: existing rows become slot_type = 'custom' via the column
-- default. Does not touch any other table. Safe to run again.
--
-- Run this BEFORE (or right after) deploying the matching code: creating or
-- editing a rule writes these columns and fails until they exist. Reading
-- rules is tolerant of the columns not existing yet.

alter table public.kalendar_custom_time_slots
  add column if not exists slot_type     text    not null default 'custom',
  add column if not exists range_start   text,
  add column if not exists range_end     text,
  add column if not exists frequency_min integer;

alter table public.kalendar_custom_time_slots
  drop constraint if exists kalendar_custom_time_slots_slot_type_check;
alter table public.kalendar_custom_time_slots
  add constraint kalendar_custom_time_slots_slot_type_check
  check (slot_type in ('custom', 'frequency'));

alter table public.kalendar_custom_time_slots
  drop constraint if exists kalendar_custom_time_slots_frequency_check;
alter table public.kalendar_custom_time_slots
  add constraint kalendar_custom_time_slots_frequency_check
  check (
    slot_type = 'custom'
    or (range_start is not null and range_end is not null and frequency_min between 1 and 720)
  );
